const { fitData, OPTIMIZERS } = DataScience;
let nn = NeuralNet.builder().input(2).positionalEncoding(6).layer(25).layer(25).layer(1,
    NeuralNet.ACTIVATIONS.sigmoid).build();
const samples = await IO.loadMNIST();
let sampleA = samples[31];
// MNIST is 28x28 = 784 1-array we want to map it into a [0,1]^2
let trainXs = Array.from(sampleA).map((_, i) => [(i % 28) / 27, 1.0 - Math.floor(i / 28) / 27]);

let thetaA;
let { theta } = fitData(trainXs, trainXs.map((_, i) => sampleA[i]), nn.model, {
    epochs: 1000,
    batch: 25,
    optimizer: OPTIMIZERS.ADAMW({ learningRate: 0.01 }),
    continuationEvery: 25,
});
thetaA = theta;

let sampleB = samples[87];
let thetaB;
thetaB = fitData(trainXs, trainXs.map((_, i) => sampleB[i]), nn.model, {
    epochs: 1000,
    batch: 20,
    optimizer: OPTIMIZERS.ADAMW({ learningRate: 0.01 }),
    continuationEvery: 25,
}).theta;

const lerpWeights = (wA, wB, t) => Object.keys(wA).reduce((weights, key) => {
    weights[key] = wA[key] * (1 - t) + wB[key] * t;
    return weights;
}, {});

const interpolationImage = IO.paintMNIST(new Float32Array(sampleB.length));
const paintInterpolationImage = interpolationImage.update;
const interpolationUI = IO.UI(
    {type: "canvas", value: () => interpolationImage},
    {type: "slider", value: () => ({
        min: 0,
        max: 1,
        onChange: value => {
            nn.setWeights(lerpWeights(thetaA, thetaB, value));
            paintInterpolationImage(Float32Array.from(trainXs.map(([x, y]) => nn.eval([x, y]))));
        },
    })},
);
interpolationUI;
